const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: false,            // no ion default imagery; we add our own below
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

// --- async provider/layer path -------------------------------------------
// Wrap the synchronous OSM constructor in a Promise so the layer goes through
// ImageryLayer.fromProviderAsync and all three event surfaces are available.
const providerPromise = Promise.resolve(
  new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 19,
    credit: 'OpenStreetMap contributors',
  })
);

const osmLayer = Cesium.ImageryLayer.fromProviderAsync(providerPromise);

// --- error-event wiring --------------------------------------------------

// 1. layer.errorEvent fires when the provider promise rejects (creation failure)
osmLayer.errorEvent.addEventListener((error) => {
  console.error('[imagery] Provider creation failed:', error);
});

// 2. layer.readyEvent fires once the promise resolves; the resolved provider
//    is passed as the argument so we can attach per-tile error listeners.
if (osmLayer.readyEvent) {
  osmLayer.readyEvent.addEventListener((provider) => {
    console.log('[imagery] Provider ready:', provider.constructor.name);

    // provider.errorEvent fires on individual tile-fetch failures
    provider.errorEvent.addEventListener((tileError) => {
      console.warn(
        '[imagery] Tile error — level:', tileError.level,
        'x:', tileError.x,
        'y:', tileError.y,
        'msg:', tileError.message
      );
    });
  });
}

// Add as index-0 base layer (globe has no other layers because baseLayer:false)
viewer.imageryLayers.add(osmLayer, 0);

// --- camera: London, top-down, ~800 km -----------------------------------
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-0.1276, 51.5074, 800000),
  orientation: {
    heading: 0.0,
    pitch: Cesium.Math.toRadians(-90),
    roll: 0.0,
  },
});
